import {RoundedBoxGeometry} from './vendor/addons/geometries/RoundedBoxGeometry.js';
import {detailMaterial,isSharedSurfaceTexture} from './surfaces.js';
import * as THREE from './vendor/three.module.js';
const materials=new Map(),sharedMaterials=new Set();
export function material(color,roughness=.72,metalness=0){const key=`${color}:${roughness}:${metalness}`;if(!materials.has(key))materials.set(key,detailMaterial(color,roughness,metalness));sharedMaterials.add(materials.get(key));return materials.get(key);}
const ballGeometry=new THREE.SphereGeometry(1,32,24),boxGeometry=new RoundedBoxGeometry(1,1,1,2,.075);
const sharedGeometry=new Set([ballGeometry,boxGeometry]),cylinders=new Map(),tubes=new Map();
const roundedBoxes=new Map();
export function roundedBox(parent,mat,pos,size,radius=.1){const key=JSON.stringify([size,radius]);if(!roundedBoxes.has(key)){const geometry=new RoundedBoxGeometry(...size,5,radius);roundedBoxes.set(key,geometry);sharedGeometry.add(geometry);}return mesh(parent,roundedBoxes.get(key),mat,pos);}
export function mesh(parent,geometry,mat,pos=[0,0,0],scale=[1,1,1]){const o=new THREE.Mesh(geometry,typeof mat==='string'?material(mat):mat);o.position.set(...pos);o.scale.set(...scale);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o;}
export const ball=(p,c,pos,scale)=>mesh(p,ballGeometry,c,pos,scale);
export const box=(p,c,pos,scale)=>mesh(p,boxGeometry,c,pos,scale);
export function cylinder(p,c,pos,top,bottom,height,segments=24){const key=[top,bottom,height,segments].join(':');if(!cylinders.has(key)){const geometry=new THREE.CylinderGeometry(top,bottom,height,segments);cylinders.set(key,geometry);sharedGeometry.add(geometry);}return mesh(p,cylinders.get(key),c,pos);}
export function tube(p,c,points,r=.025,segments=24,radialSegments=8){const key=JSON.stringify([points,r,segments,radialSegments]);if(!tubes.has(key)){const geometry=new THREE.TubeGeometry(new THREE.CatmullRomCurve3(points.map(v=>new THREE.Vector3(...v))),segments,r,radialSegments,false);tubes.set(key,geometry);sharedGeometry.add(geometry);}return mesh(p,tubes.get(key),c);}
export function signTexture(text,{background='#fff1ce',color='#334d56',width=256,height=96}={}){const c=document.createElement('canvas');c.width=width;c.height=height;const x=c.getContext('2d');x.fillStyle=background;x.fillRect(0,0,width,height);x.strokeStyle=color;x.lineWidth=3;x.strokeRect(5,5,width-10,height-10);x.fillStyle=color;x.textAlign='center';x.textBaseline='middle';x.font=`bold ${Math.min(36,(width-20)/Math.max(1,text.length))}px "Microsoft YaHei",sans-serif`;x.fillText(text,width/2,height/2);const t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;return t;}
export function sign(p,text,pos,w=1.2,h=.35,options={}){const m=new THREE.MeshBasicMaterial({map:signTexture(text,options),side:THREE.DoubleSide});return mesh(p,new THREE.PlaneGeometry(w,h),m,pos);}
export function disposeUnique(root){const ownedGeometry=new Set(),ownedMaterials=new Set(),ownedTextures=new Set();root.traverse(o=>{if(o.isInstancedMesh)o.dispose();if(o.geometry&&!sharedGeometry.has(o.geometry))ownedGeometry.add(o.geometry);for(const mat of (Array.isArray(o.material)?o.material:[o.material]))if(mat&&!sharedMaterials.has(mat)){ownedMaterials.add(mat);for(const key of ['map','bumpMap','normalMap','roughnessMap'])if(mat[key]&&!isSharedSurfaceTexture(mat[key]))ownedTextures.add(mat[key]);}});for(const geometry of ownedGeometry)geometry.dispose();for(const texture of ownedTextures)texture.dispose();for(const mat of ownedMaterials)mat.dispose();}
// Batch repeated windows, fence posts and masonry without changing silhouette.
export function batchStatic(root){root.updateMatrixWorld(true);const inverse=root.matrixWorld.clone().invert(),groups=new Map();root.traverse(o=>{let parent=o;while(parent&&parent!==root){if(parent.userData.dynamic||!parent.visible)return;parent=parent.parent;}if(o.isMesh&&!o.isInstancedMesh&&sharedGeometry.has(o.geometry)&&(!o.material.map||isSharedSurfaceTexture(o.material.map))){const key=[o.geometry.uuid,o.material.uuid,o.castShadow,o.receiveShadow,o.renderOrder,o.layers.mask].join(':');const list=groups.get(key)||[];list.push(o);groups.set(key,list);}});for(const list of groups.values()){if(list.length<2)continue;const first=list[0],batch=new THREE.InstancedMesh(first.geometry,first.material,list.length);batch.castShadow=first.castShadow;batch.receiveShadow=first.receiveShadow;batch.renderOrder=first.renderOrder;batch.layers.mask=first.layers.mask;for(const [i,o]of list.entries()){batch.setMatrixAt(i,new THREE.Matrix4().multiplyMatrices(inverse,o.matrixWorld));o.parent.remove(o);}batch.computeBoundingSphere();root.add(batch);}return root;}
